def parse_form(value: str) -> tuple[str, str | None]:
    if "|" in value:
        text, tr = value.split("|", 1)
        return text, tr
    return value, None


def E(en: str, **forms: str) -> dict:
    missing = set(LANG_FROM_ARG) - set(forms)
    extra = set(forms) - set(LANG_FROM_ARG)
    if missing or extra:
        raise ValueError(f"{en}: missing={sorted(missing)} extra={sorted(extra)}")
    out: dict[str, tuple[str, str | None]] = {"en": (en, None)}  # type: ignore[assignment]
    packed: dict[str, tuple[str, str | None]] = {}
    for arg, code in LANG_FROM_ARG.items():
        packed[code] = parse_form(forms[arg])
    packed["en"] = (en, None)
    return packed


def _check(rows: list[dict]) -> list[dict]:
    return rows


